// Python-compatible string case helpers.
// These mirror the exact semantics of CPython's str.lower/upper/title
// and str.islower/isupper/istitle for the cases the inflection code
// relies on (including mixed-case and non-letter boundaries).

function isCased(ch) {
  return ch.toLowerCase() !== ch.toUpperCase();
}

function isUpperChar(ch) {
  return isCased(ch) && ch === ch.toUpperCase();
}

function isLowerChar(ch) {
  return isCased(ch) && ch === ch.toLowerCase();
}

function isLetter(ch) {
  return /\p{L}/u.test(ch);
}

// str.islower(): at least one cased char, and every cased char is lowercase.
export function pyIsLower(s) {
  let any = false;
  for (const ch of s) {
    if (!isCased(ch)) continue;
    if (!isLowerChar(ch)) return false;
    any = true;
  }
  return any;
}

// str.isupper(): at least one cased char, and every cased char is uppercase.
export function pyIsUpper(s) {
  let any = false;
  for (const ch of s) {
    if (!isCased(ch)) continue;
    if (!isUpperChar(ch)) return false;
    any = true;
  }
  return any;
}

// str.istitle(): uppercase chars may only start a word (previous char
// uncased), lowercase chars may only follow a cased char.
export function pyIsTitle(s) {
  let any = false;
  let prevCased = false;
  for (const ch of s) {
    if (isUpperChar(ch)) {
      if (prevCased) return false;
      prevCased = true;
      any = true;
    } else if (isLowerChar(ch)) {
      if (!prevCased) return false;
      prevCased = true;
      any = true;
    } else {
      prevCased = false;
    }
  }
  return any;
}

// str.title(): uppercase the first letter of every word (words are runs
// of letters), lowercase the remaining letters of each word.
export function pyTitle(s) {
  let out = '';
  let prevLetter = false;
  for (const ch of s) {
    if (isLetter(ch)) {
      out += prevLetter ? ch.toLowerCase() : ch.toUpperCase();
      prevLetter = true;
    } else {
      out += ch;
      prevLetter = false;
    }
  }
  return out;
}

export function pyLower(s) {
  return s.toLowerCase();
}

export function pyUpper(s) {
  return s.toUpperCase();
}

