// English noun inflection tables.
//
// These tables were reconstructed black-box from the reference behavior:
// whole-word lookups (uninflected words and irregular pairs) plus the
// small closed word lists that receive special suffix handling. Any word
// not listed here falls through to the generic suffix rules in
// inflect.mjs.

// Words whose plural is identical to the singular, plus plural forms that
// must not be re-pluralized (irregular plurals and the plural forms of
// the special lists below that do not already end in "es").
export const UNINFLECTED = new Set([
  // singular uninflected
  'bison', 'corps', 'deer', 'fish', 'means', 'moose', 'offspring',
  'scissors', 'series', 'sheep', 'species', 'formulas',
  // irregular plurals
  'people', 'men', 'women', 'children', 'feet', 'teeth', 'geese', 'mice',
  'lice', 'oxen', 'dice', 'corpora', 'firemen', 'milennia',
  // -us -> -i plurals
  'alumni', 'cacti', 'foci', 'fungi', 'hippopotami', 'nuclei', 'octopi',
  'radii', 'stimuli', 'syllabi',
  // -um -> -a plurals
  'addenda', 'bacteria', 'curricula', 'data', 'errata', 'media',
  'memoranda', 'ova', 'strata', 'symposia',
  // -on -> -a plurals
  'criteria', 'phenomena',
  // -a -> -ae plurals
  'algae', 'alumnae', 'antennae', 'nebulae', 'vertebrae',
]);

// Irregular singular -> plural pairs (whole-word matches only).
export const IRREGULAR_PLURALS = new Map([
  ['child', 'children'],
  ['corpus', 'corpora'],
  ['die', 'dice'],
  ['fireman', 'firemen'],
  ['foot', 'feet'],
  ['goose', 'geese'],
  ['louse', 'lice'],
  ['man', 'men'],
  ['millennium', 'milennia'],
  ['mouse', 'mice'],
  ['ox', 'oxen'],
  ['person', 'people'],
  ['tooth', 'teeth'],
  ['woman', 'women'],
]);

// -is -> -es  (analysis -> analyses)
export const IS_TO_ES = new Set([
  'analysis', 'axis', 'basis', 'crisis', 'diagnosis', 'ellipsis',
  'emphasis', 'hypothesis', 'neurosis', 'oasis', 'parenthesis',
  'synopsis', 'thesis',
]);

// -us -> -i  (cactus -> cacti)
export const US_TO_I = new Set([
  'alumnus', 'cactus', 'focus', 'fungus', 'hippopotamus', 'nucleus',
  'octopus', 'radius', 'stimulus', 'syllabus',
]);

// -um -> -a  (datum -> data)
export const UM_TO_A = new Set([
  'addendum', 'bacterium', 'curriculum', 'datum', 'erratum', 'medium',
  'memorandum', 'ovum', 'stratum', 'symposium',
]);

// -on -> -a  (criterion -> criteria)
export const ON_TO_A = new Set([
  'criterion', 'phenomenon',
]);

// -ex/-ix -> -ices  (index -> indices, matrix -> matrices)
export const EX_IX_TO_ICES = new Set([
  'appendix', 'index', 'matrix',
]);

// -a -> -ae  (alga -> algae)
export const A_TO_AE = new Set([
  'alga', 'alumna', 'antenna', 'nebula', 'vertebra',
]);

// -o -> -oes  (potato -> potatoes)
export const O_TO_OES = new Set([
  'echo', 'embargo', 'hero', 'mosquito', 'potato', 'tomato', 'torpedo',
  'veto',
]);

// -f -> -ves  (wolf -> wolves)
export const F_TO_VES = new Set([
  'calf', 'dwarf', 'elf', 'half', 'hoof', 'leaf', 'loaf', 'scarf', 'self',
  'shelf', 'thief', 'wolf',
]);

// -fe -> -ves  (knife -> knives)
export const FE_TO_VES = new Set([
  'knife', 'life', 'wife',
]);

