// Minimal re-implementation of the argparse behavior used by the original
// script: two required string options (--a, --b) plus -h/--help, with
// matching usage/help text, error messages, and exit codes.

import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor() {
    this.prog = basename(process.argv[1] || 'test12.mjs');
    this.options = [];
  }

  addArgument(flag, { required = false, help = '' } = {}) {
    this.options.push({
      flag,
      metavar: flag.replace(/^-+/, '').toUpperCase(),
      required,
      help,
    });
  }

  formatUsage() {
    const parts = this.options.map((o) => `${o.flag} ${o.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  formatHelp() {
    const invocations = ['-h, --help'];
    const helps = ['show this help message and exit'];
    for (const o of this.options) {
      invocations.push(`${o.flag} ${o.metavar}`);
      helps.push(o.help);
    }
    const helpPos = 2 + Math.max(...invocations.map((s) => s.length)) + 2;
    const lines = invocations.map(
      (inv, i) => '  ' + inv.padEnd(helpPos - 2) + helps[i],
    );
    return `${this.formatUsage()}\n\noptions:\n${lines.join('\n')}\n`;
  }

  error(message) {
    process.stderr.write(`${this.formatUsage()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const byFlag = new Map(this.options.map((o) => [o.flag, o]));
    const values = new Map();
    const extras = [];
    let sawSeparator = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (sawSeparator) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        sawSeparator = true;
        continue;
      }
      if (token === '-h' || token === '--help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }
      let flag = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        flag = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
      const opt = byFlag.get(flag);
      if (opt) {
        if (inlineValue !== null) {
          values.set(opt.flag, inlineValue);
        } else {
          const next = argv[i + 1];
          const looksLikeOption =
            next !== undefined &&
            next.length > 1 &&
            next.startsWith('-') &&
            !NEGATIVE_NUMBER.test(next);
          if (next === undefined || looksLikeOption) {
            this.error(`argument ${opt.flag}: expected one argument`);
          }
          values.set(opt.flag, next);
          i++;
        }
      } else {
        extras.push(token);
      }
    }

    const missing = this.options
      .filter((o) => o.required && !values.has(o.flag))
      .map((o) => o.flag);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const result = {};
    for (const o of this.options) {
      const key = o.flag.replace(/^-+/, '');
      result[key] = values.get(o.flag);
    }
    return result;
  }
}

