cd /tmp/probe && awk 'BEGIN{
  srand(42);
  stems["n"]=0; split("b c d f g k l m n p r s t v w z bl tr str qu cr fl gr pr sn th chr sch", st, " ");
  split("a e i o u a e o", vow, " ");
  split("s ss sh ch x z y ey ay oy uy o eo io f fe ff is us um on a e i es ing er", suf, " ");
  for(i=0;i<900;i++){
    w="";
    nl=int(rand()*3)+1;
    for(j=0;j<nl;j++){ w=w st[int(rand()*24)+1] vow[int(rand()*8)+1]; }
    w=w suf[int(rand()*26)+1];
    r=rand();
    if(r<0.15){ w=toupper(w); }
    else if(r<0.3){ w=toupper(substr(w,1,1)) substr(w,2); }
    else if(r<0.4){ # random casing
      nw="";
      for(j=1;j<=length(w);j++){ c=substr(w,j,1); nw = nw (rand()<0.5 ? toupper(c) : c); }
      w=nw;
    }
    print w;
  }
}' > fuzz.txt
sort -u fuzz.txt -o fuzz.txt; wc -l fuzz.txt
xargs -P 16 -I{} ./diff_one.sh {} < fuzz.txt > fuzz_mismatches.txt
wc -l fuzz_mismatches.txt; head -40 fuzz_mismatches.txt

